    if (m && ids.indexOf(m[1]) >= 0) setOpen(m[1]);
    const pop = () => { const mm = /^\/stories\/([a-z0-9-]+)/.exec(window.location.pathname || ""); setOpen(mm && JR17[mm[1]] ? mm[1] : null); };
